(()=>{
"use strict";
window.CG50DirectFrames=true;
let source=null,queued=false;
const views=[];
function place(v){
  const r=v.image.getBoundingClientRect(),p=v.parent.getBoundingClientRect();
  Object.assign(v.canvas.style,{
    left:(r.left-p.left-v.parent.clientLeft+v.parent.scrollLeft)+"px",
    top:(r.top-p.top-v.parent.clientTop+v.parent.scrollTop)+"px",
    width:r.width+"px",height:r.height+"px"
  });
}
function paint(){
  queued=false;
  if(!source)return;
  for(const v of views){
    place(v);
    if(!v.image.getBoundingClientRect().width)continue;
    if(v.canvas.width!==source.width||v.canvas.height!==source.height){
      v.canvas.width=source.width;v.canvas.height=source.height;
    }
    v.context.imageSmoothingEnabled=false;
    v.context.drawImage(source,0,0);
  }
  const status=document.getElementById("connection");
  if(status&&!window.CG50ConnectionStatusManaged){
    const text=document.documentElement.lang.startsWith("en")
      ?"Screen connected":"画面已连接";
    if(status.textContent!==text)status.textContent=text;
    status.classList.add("online");
  }
}
function schedule(){
  if(!queued){queued=true;requestAnimationFrame(paint);}
}
window.CG50PaintFrame=c=>{source=c;schedule();};
function install(){
  for(const image of document.querySelectorAll("img.lcd")){
    const parent=image.parentElement;
    if(getComputedStyle(parent).position==="static")
      parent.style.position="relative";
    const canvas=document.createElement("canvas");
    canvas.setAttribute("aria-hidden","true");
    canvas.style.cssText="position:absolute;pointer-events:none;object-fit:contain;background:#000;z-index:1;image-rendering:pixelated;";
    parent.append(canvas);
    image.style.visibility="hidden";
    const v={image,parent,canvas,context:canvas.getContext("2d")};
    views.push(v);place(v);
    if(typeof ResizeObserver==="function"){
      const observer=new ResizeObserver(()=>{place(v);schedule();});
      observer.observe(image);observer.observe(parent);
    }
  }
  const capture=document.getElementById("capture");
  if(capture)capture.onclick=()=>{
    if(!source)return;
    const c=document.createElement("canvas");c.width=384;c.height=216;
    c.getContext("2d").drawImage(source,0,0,384,216);
    c.toBlob(blob=>{
      if(!blob)return;
      const url=URL.createObjectURL(blob),a=document.createElement("a");
      a.href=url;a.download="CG50-Pro-Max-"+Date.now()+".png";
      a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
    },"image/png");
  };
  window.addEventListener("resize",schedule);
  schedule();
}
if(document.readyState==="loading")
  document.addEventListener("DOMContentLoaded",install,{once:true});
else install();
})();

window.CG50Release={"app": "CG50 Pro Max", "version": "1.1.0", "releaseId": "v1.1.0-20261013-161753", "graphicsAcceleration": true, "notesZh": ["支持设备上的触屏轻震反馈，并保留按键高亮。", "画图忙时自动加速，空闲时降低占用。", "新增版本号与更新说明弹窗。", "左上角显示联网同步、更新或离线状态。", "重载配置文件后显示成功或失败，成功时显示版本号。", "新用户采用未初始化的初始存档；已有进度保留。"], "notesEn": ["Touch vibration on supported devices, with visual key feedback.", "Automatic acceleration while busy and reduced work while idle.", "Version information and release notes.", "Online, update and offline status in the header.", "Reload result feedback with the installed version.", "An uninitialized starting state for new users. Existing progress is retained."]};
window.CG50ConnectionStatusManaged=true;

(()=>{
"use strict";
const release=window.CG50Release;
const zh=()=>!document.documentElement.lang.startsWith("en");
const text=(a,b)=>zh()?a:b;
const seenKey="cg50.last-announced-release";
let notices=Promise.resolve(),consumed=new Set();
window.CG50Notice=options=>{
 notices=notices.catch(()=>{}).then(()=>new Promise(resolve=>{
  const show=()=>{
   if(!document.body){setTimeout(show,100);return;}
   if(!options.force&&document.querySelector("dialog[open]")){
    setTimeout(show,200);return;
   }
   const dialog=document.createElement("dialog");
   dialog.id="cg50-feedback-dialog";
   dialog.style.cssText="max-width:430px;width:calc(100% - 40px);box-sizing:border-box;border:1px solid #879bb3;border-radius:16px;padding:24px;font:16px/1.6 -apple-system,sans-serif;";
   const style=getComputedStyle(document.body);
   dialog.style.background=style.backgroundColor;dialog.style.color=style.color;
   const title=document.createElement("h2");
   title.style.cssText="font-size:22px;margin:0 0 12px";
   title.textContent=options.title;
   const body=document.createElement("p");body.textContent=options.body||"";
   dialog.append(title,body);
   if(options.items?.length){
    const list=document.createElement("ul");
    for(const item of options.items){
     const li=document.createElement("li");li.textContent=item;list.append(li);
    }
    dialog.append(list);
   }
   const close=document.createElement("button");
   close.type="button";close.textContent=text("知道啦","Got it");
   close.style.cssText="font:inherit;border:0;border-radius:10px;background:#245fe0;color:white;padding:10px 20px;cursor:pointer";
   close.onclick=()=>dialog.close();dialog.append(close);document.body.append(dialog);
   dialog.addEventListener("close",()=>{dialog.remove();resolve();},{once:true});
   if(typeof releaseAll==="function")releaseAll();
   dialog.showModal();close.focus();
  };
  show();
 }));
 return notices;
};
window.addEventListener("keydown",e=>{
 const dialog=document.getElementById("cg50-feedback-dialog");
 if(!dialog?.open||e.metaKey||e.ctrlKey)return;
 consumed.add(e.code);e.preventDefault();e.stopImmediatePropagation();
 if(!e.repeat&&["Escape","Enter"," "].includes(e.key))dialog.close();
},true);
window.addEventListener("keyup",e=>{
 if(consumed.delete(e.code)||document.getElementById("cg50-feedback-dialog")?.open){
  e.preventDefault();e.stopImmediatePropagation();
 }
},true);
window.CG50ShowRelease=async(force=false,extra="")=>{
 let seen=null;try{seen=localStorage.getItem(seenKey);}catch(_){}
 if(!force&&seen===release.releaseId&&!extra)return;
 const changed=seen!==release.releaseId;
 await window.CG50Notice({
  title:extra?text("重载成功啦","Reload successful"):text("新版已就位啦！","Update ready!"),
  body:extra||text("当前版本：v","Current version: v")+release.version,
  items:force||changed?(zh()?release.notesZh:release.notesEn):[]
 });
 try{localStorage.setItem(seenKey,release.releaseId);}catch(_){}
};
function install(){
 document.addEventListener("pointerdown",e=>{
  if(!e.isTrusted||!["touch","pen"].includes(e.pointerType))return;
  const button=e.target.closest?.("button");
  if(!button||button.disabled)return;
  try{if(typeof navigator.vibrate==="function")navigator.vibrate(10);}catch(_){}
  button.classList.add("cg50-touch-feedback");
  setTimeout(()=>button.classList.remove("cg50-touch-feedback"),100);
 },{capture:true,passive:true});
 const css=document.createElement("style");
 css.textContent=".cg50-touch-feedback{outline:2px solid #67adff!important;outline-offset:-2px}";
 document.head.append(css);
 const settings=document.getElementById("cg50-settings-dialog");
 if(settings){
  const row=document.createElement("p");row.id="cg50-current-version";
  const button=document.createElement("button");
  button.type="button";button.id="cg50-release-notes";
  const labels=()=>{
   row.textContent=text("版本：v","Version: v")+release.version;
   button.textContent=text("查看更新说明","Release notes");
  };
  labels();settings.append(row,button);
  new MutationObserver(labels).observe(document.documentElement,{
   attributes:true,attributeFilter:["lang"]
  });
  button.onclick=()=>{settings.close();window.CG50ShowRelease(true);};
 }
 startup();
}
async function startup(){
 let pending=null;
 try{pending=JSON.parse(sessionStorage.getItem("cg50.reload-result.v1")||"null");}catch(_){}
 if(pending&&Date.now()-pending.at>600000){
  sessionStorage.removeItem("cg50.reload-result.v1");pending=null;
 }
 let timer,onFault;
 try{
  const fault=new Promise((_,reject)=>{
   onFault=e=>reject(Error(e.detail||"Core startup failed"));
   window.addEventListener("cg50-core-fault",onFault,{once:true});
  });
  if(window.CG50CoreFault)throw Error(window.CG50CoreFault);
  const ready=Promise.all([window.CG50EmulatorReady,window.CG50FirstFrameReady]);
  if(pending){
   const timeout=new Promise((_,reject)=>{
    timer=setTimeout(()=>reject(Error(text("核心启动超时","Core startup timed out"))),60000);
   });
   await Promise.race([ready,fault,timeout]);
  }else await Promise.race([ready,fault]);
  if(pending)sessionStorage.removeItem("cg50.reload-result.v1");
  if(pending?.kind==="manual"){
   if(pending.expected&&pending.expected!==release.releaseId)
    throw Error(text("新版尚未载入，当前仍为 v","The update has not loaded. Current version: v")+release.version);
   const extra=text("配置文件已重载，当前版本 v","Configuration reloaded. Current version v")+release.version+
    (pending.offline?text("（使用离线缓存）"," (using offline cache)"):"");
   await window.CG50ShowRelease(false,extra);
  }else await window.CG50ShowRelease();
 }catch(error){
  if(pending){
   sessionStorage.removeItem("cg50.reload-result.v1");
   window.CG50Notice({force:true,title:text("重载没完成哦","Reload failed"),body:error.message});
  }
 }finally{
  clearTimeout(timer);
  if(onFault)window.removeEventListener("cg50-core-fault",onFault);
 }
}
if(document.readyState==="loading")
 document.addEventListener("DOMContentLoaded",install,{once:true});
else install();
})();

(()=>{
"use strict";
const release=window.CG50Release;
window.CG50ConnectionStatusManaged=true;
const zh=()=>!document.documentElement.lang.startsWith("en");
const text=(a,b)=>zh()?a:b;
let registration=null,busy=false,checking=false,approved=false,needsReload=false,ready=false;
let latest=null,network="checking",lastInput=Date.now();
let firstController=!navigator.serviceWorker?.controller,lastCheck=0;
const registered=("serviceWorker" in navigator)
 ?navigator.serviceWorker.register("./sw.js",{updateViaCache:"none"}).catch(()=>null)
 :Promise.resolve(null);
function status(value){network=value;renderStatus();}
function renderStatus(){
 const el=document.getElementById("connection");if(!el)return;
 const labels={
  checking:text("检查更新中…","Checking updates…"),
  current:text("在线 · 已同步","Online · Up to date"),
  available:text("在线 · 有更新","Online · Update available"),
  offline:text("离线使用","Offline"),
  updating:text("在线 · 更新中…","Online · Updating…")
 };
 const value=labels[network]||labels.offline;
 if(el.textContent!==value)el.textContent=value;
 el.classList.toggle("online",["current","available","updating"].includes(network));
 el.title=text("当前版本 v","Current version v")+release.version;
}
function newer(meta){
 const a=meta.version.split(".").map(Number),b=release.version.split(".").map(Number);
 for(let i=0;i<3;i++){if(a[i]!==b[i])return a[i]>b[i];}
 return meta.releaseId!==release.releaseId;
}
async function handshake(){
 if(navigator.onLine===false){latest=null;status("offline");return null;}
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),6000);
 try{
  const url=new URL("./version.json",location.href);
  url.searchParams.set("check",String(Date.now()));
  const response=await fetch(url.href,{cache:"no-store",signal:controller.signal});
  if(!response.ok)throw Error("Version check failed");
  const value=await response.json();
  if(value.app!=="CG50 Pro Max"||!(/^\d+\.\d+\.\d+$/).test(value.version)||
      typeof value.releaseId!=="string"||!value.releaseId)
   throw Error("Invalid version response");
  latest=value;status(newer(value)?"available":"current");return value;
 }catch(_){latest=null;status("offline");return null;}
 finally{clearTimeout(timer);}
}
function safe(){
 return ready&&!document.hidden&&Date.now()-lastInput>=2500&&
  !document.querySelector("dialog[open]");
}
function notice(show){
 document.getElementById("cg50-update-notice")?.remove();
 if(!show)return;
 const box=document.createElement("div");box.id="cg50-update-notice";
 box.textContent=text("正在保存进度并准备更新…","Saving progress and preparing the update…");
 box.style.cssText="position:fixed;bottom:14px;right:14px;padding:12px 16px;border-radius:10px;background:#245fe0;color:white;z-index:9999;font:14px system-ui";
 document.body.append(box);
}
function workerRelease(worker){
 return new Promise(resolve=>{
  const channel=new MessageChannel();
  const finish=value=>{clearTimeout(timer);channel.port1.close();resolve(value);};
  const timer=setTimeout(()=>finish(null),2000);
  channel.port1.onmessage=e=>finish(e.data);
  try{worker.postMessage("GET_RELEASE",[channel.port2]);}catch(_){finish(null);}
 });
}
async function waitForWorker(expected){
 const deadline=Date.now()+180000;
 while(Date.now()<deadline){
  const worker=registration?.waiting;
  if(worker){
   const meta=await workerRelease(worker);
   if(meta?.releaseId===expected)return worker;
  }
  if(!registration?.installing&&!registration?.waiting)
   throw Error(text("新版下载未完成，请稍后重试","Update download did not complete. Please retry."));
  await new Promise(resolve=>setTimeout(resolve,200));
 }
 throw Error(text("新版下载超时，请稍后重试","Update download timed out. Please retry."));
}
async function save(){
 if(typeof releaseAll==="function")releaseAll();
 const controller=new AbortController();let timer;
 const job=(async()=>{
  if(typeof chain!=="undefined")await chain;
  const response=await fetch("/save",{
   method:"POST",cache:"no-store",signal:controller.signal
  });
  if(!response.ok||(await response.text()).trim()!=="state saved")
   throw Error(text("进度未能保存，已取消重载","Progress could not be saved. Reload cancelled."));
 })();
 try{
  await Promise.race([job,new Promise((_,reject)=>{
   timer=setTimeout(()=>{
    controller.abort();
    reject(Error(text("保存超时，已取消重载","Saving timed out. Reload cancelled.")));
   },15000);
  })]);
 }finally{clearTimeout(timer);}
}
function remember(kind,offline,expected){
 sessionStorage.setItem("cg50.reload-result.v1",
  JSON.stringify({kind,offline,expected,at:Date.now()}));
}
async function apply(manual=false){
 if(busy||checking){
  if(manual)throw Error(text("正在检查更新，请稍后再试","An update check is running. Please retry."));
  return;
 }
 registration=await registered;
 if(!ready){
  if(manual)throw Error(text("计算器还在启动，等一下再重载哦","The calculator is starting. Please wait."));
  return;
 }
 if(!manual&&(!safe()||(!registration?.waiting&&!needsReload)))return;
 busy=true;approved=false;notice(true);
 try{
  const remote=await handshake();
  if(!manual&&(!remote||!safe()))return;
  let waiting=null;
  if(manual&&remote&&registration){
   await registration.update();
   if(newer(remote))waiting=await waitForWorker(remote.releaseId);
  }
  if(remote&&registration?.waiting){
   const meta=await workerRelease(registration.waiting);
   if(meta?.releaseId===remote.releaseId)waiting=registration.waiting;
  }
  if(!manual&&!waiting&&!needsReload)return;
  await save();
  remember(manual?"manual":"update",!remote,waiting?remote.releaseId:null);
  approved=true;
  if(waiting&&waiting.state!=="activated"){
   if(remote)status("updating");
   await new Promise((resolve,reject)=>{
    const timer=setTimeout(()=>{
     navigator.serviceWorker.removeEventListener("controllerchange",changed);
     reject(Error(text("更新激活超时，请重试","Update activation timed out. Please retry.")));
    },20000);
    const changed=()=>{
     clearTimeout(timer);
     navigator.serviceWorker.removeEventListener("controllerchange",changed);
     resolve();
    };
    navigator.serviceWorker.addEventListener("controllerchange",changed);
    waiting.postMessage("ACTIVATE_UPDATE");
   });
  }
  location.reload();
 }catch(error){
  approved=false;
  try{sessionStorage.removeItem("cg50.reload-result.v1");}catch(_){}
  if(manual)throw error;
  console.warn("Update postponed",error);
 }finally{busy=false;notice(false);}
}
async function check(force=false){
 if(busy||checking||document.hidden||(!force&&Date.now()-lastCheck<15000))return;
 checking=true;lastCheck=Date.now();
 try{
  const remote=await handshake();
  registration=await registered;
  if(remote&&registration)await registration.update();
 }catch(_){}finally{checking=false;}
 apply();
}
window.CG50ManualReload=()=>apply(true);
window.CG50UpdateService={check:()=>handshake(),getState:()=>network};
for(const type of ["pointerdown","keydown","click"]){
 window.addEventListener(type,e=>{
  lastInput=Date.now();
  if(busy&&!e.metaKey&&!e.ctrlKey){e.preventDefault();e.stopImmediatePropagation();}
 },true);
}
if("serviceWorker" in navigator)
 navigator.serviceWorker.addEventListener("controllerchange",()=>{
  if(firstController){firstController=false;return;}
  if(busy&&approved)return;
  needsReload=true;apply();
 });
function install(){
 renderStatus();
 new MutationObserver(renderStatus).observe(document.documentElement,{
  attributes:true,attributeFilter:["lang"]
 });
 const dialog=document.getElementById("cg50-settings-dialog");
 if(dialog){
  const row=document.createElement("div"),button=document.createElement("button");
  const hint=document.createElement("p");
  button.id="cg50-reload-config";button.type="button";
  button.style.cssText="font:inherit;padding:10px 14px;border-radius:9px;cursor:pointer";
  const labels=()=>{
   button.textContent=text("重载配置文件","Reload configuration");
   hint.textContent=text("先保存进度，重载后显示结果和版本号。",
    "Save progress, then reload and show the result and version.");
  };
  labels();row.append(button,hint);dialog.append(row);
  new MutationObserver(labels).observe(document.documentElement,{
   attributes:true,attributeFilter:["lang"]
  });
  button.onclick=async()=>{
   button.disabled=true;dialog.close();
   try{await apply(true);}
   catch(error){
    await window.CG50Notice({title:text("重载没完成哦","Reload failed"),body:error.message});
   }finally{button.disabled=false;}
  };
 }
 Promise.all([window.CG50EmulatorReady,window.CG50FirstFrameReady])
  .then(()=>{ready=true;apply();}).catch(()=>{});
 check(true);setInterval(check,60000);setInterval(()=>apply(),3000);
 window.addEventListener("online",()=>check(true));
 window.addEventListener("offline",()=>{latest=null;status("offline");});
 window.addEventListener("focus",()=>check());
 document.addEventListener("visibilitychange",()=>{if(!document.hidden)check();});
}
if(document.readyState==="loading")
 document.addEventListener("DOMContentLoaded",install,{once:true});
else install();
})();

(()=>{
"use strict";
window.CG50NativeCompact=false;
try {
    window.CG50NativeCompact=localStorage.getItem("cg50-mini")==="true";
} catch (_) {}
const networkFetch=window.fetch.bind(window);
const worker=new Worker("./worker.js");
const pending=new Map();
let seq=0, active=false, fault="", frameReady=false, saveBusy=false;
const canvas=document.createElement("canvas");
const ctx=canvas.getContext("2d");
let readyResolve;
const sessionReady=new Promise(r=>readyResolve=r);
window.CG50EmulatorReady=sessionReady;
let firstFrameResolve;
window.CG50FirstFrameReady=new Promise(r=>firstFrameResolve=r);
window.CG50ReportCoreFault=error=>{
  window.CG50CoreFault=String(error);
  window.dispatchEvent(new CustomEvent("cg50-core-fault",{
    detail:window.CG50CoreFault
  }));
};


function rpc(action,data={}){
  // V100 INPUT CACHE
  if(action==="boot"){
    let speed=5000000;
    try { speed=Number(localStorage.getItem("cg50-input-ips-v1"))||speed; } catch(_){}
    data={...data,inputSpeed:speed};
  }
  return new Promise((resolve,reject)=>{
    const id=++seq;
    const timer=setTimeout(()=>{
      pending.delete(id);reject(Error("Emulator timed out"));
    },30000);
    pending.set(id,{resolve,reject,timer});
    worker.postMessage({id,action,...data});
  });
}
function notify(text){
  console.log("[CG50 iPad]",text);
  const el=document.getElementById("ipad-status");
  if(el)el.textContent=text;
}

worker.onmessage=({data:m})=>{
  if(m.type==="input-speed"){
    try { localStorage.setItem("cg50-input-ips-v1",String(m.value)); } catch(_){}
    return;
  }
  if(m.type==="frame"){
    if(canvas.width!==m.width||canvas.height!==m.height){
      canvas.width=m.width;canvas.height=m.height;
    }
    ctx.putImageData(new ImageData(
      new Uint8ClampedArray(m.pixels),m.width,m.height),0,0);

frameReady=true;
    if(firstFrameResolve){firstFrameResolve();firstFrameResolve=null;}
    if(window.CG50PaintFrame)window.CG50PaintFrame(canvas);
    return;
  }
  if(m.type==="fault"){
    fault=m.error;window.CG50ReportCoreFault(fault);notify("Emulator stopped: "+fault);
    alert("CG50 emulator stopped:\n"+fault);return;
  }
  const p=pending.get(m.id);
  if(!p)return;
  clearTimeout(p.timer);pending.delete(m.id);
  m.error?p.reject(Error(m.error)):p.resolve(m.result);
};
worker.onerror=e=>{
  fault=e.message;window.CG50ReportCoreFault(fault);
  notify("Worker error: "+fault);
};

const dbReady=new Promise((resolve,reject)=>{
  const r=indexedDB.open("cg50-ipad-v1",1);
  r.onupgradeneeded=()=>r.result.createObjectStore("files");
  r.onsuccess=()=>resolve(r.result);
  r.onerror=()=>reject(r.error);
});
async function read(key){
  const db=await dbReady;
  return new Promise((resolve,reject)=>{
    const r=db.transaction("files").objectStore("files").get(key);
    r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);
  });
}
async function write(values){
  const db=await dbReady;
  return new Promise((resolve,reject)=>{
    const t=db.transaction("files","readwrite");
    for(const [k,v] of Object.entries(values))
      t.objectStore("files").put(v,k);
    t.oncomplete=resolve;
    t.onabort=()=>reject(t.error||Error("Storage write failed"));
    t.onerror=()=>reject(t.error);
  });
}
async function boot(flash,state){
  try {
    await rpc("boot",{flash,state});
  } catch(error) {
    window.CG50ReportCoreFault(error);
    throw error;
  }
  active=true;readyResolve();
}
async function snapshot(){
  if(fault)throw Error(fault);
  const state=await rpc("save");
  await write({state});
}
function waitReady(signal){
  if(signal?.aborted)return Promise.reject(
    new DOMException("Aborted","AbortError"));
  if(active)return Promise.resolve();
  return new Promise((resolve,reject)=>{
    const abort=()=>reject(new DOMException("Aborted","AbortError"));
    signal?.addEventListener("abort",abort,{once:true});
    sessionReady.then(()=>{
      signal?.removeEventListener("abort",abort);resolve();
    });
  });
}
const endpoints=new Set(["/frame","/key","/hold","/save","/load"]);
window.fetch=async(input,options={})=>{
  const u=new URL(input instanceof Request?input.url:input,location.href);
  if(u.origin!==location.origin||!endpoints.has(u.pathname))
    return networkFetch(input,options);
  const signal=options.signal||(input instanceof Request?input.signal:null);
  await waitReady(signal);
  if(fault)return new Response(fault,{status:503});
  try{
    if(u.pathname==="/frame"){
      if(!frameReady)return new Response("Starting",{status:503});
      const blob=await new Promise(r=>canvas.toBlob(r,"image/png"));
      return new Response(blob,{headers:{"Content-Type":"image/png"}});
    }
    if(u.pathname==="/key")
      await rpc("key",{key:u.searchParams.get("k")});
    if(u.pathname==="/hold"){
      if(u.searchParams.has("reset"))await rpc("release");
      else await rpc("hold",{
        key:u.searchParams.get("k"),
        token:u.searchParams.get("id")||"pointer",
        down:u.searchParams.get("down")==="1"
      });
    }
    if(u.pathname==="/save"){
      await snapshot();return new Response("state saved");
    }
    if(u.pathname==="/load"){
      const state=await read("state");
      if(!state)throw Error("No saved progress");
      await rpc("load",{state});
      return new Response("state reloaded");
    }
    return new Response(null,{status:204});
  }catch(e){return new Response(String(e),{status:500});}
};
async function automaticSave(){
  if(!active||fault||saveBusy)return;
  saveBusy=true;
  try{await rpc("release");await snapshot();}
  catch(e){notify("Automatic save failed: "+e.message);}
  finally{saveBusy=false;}
}
document.addEventListener("visibilitychange",()=>{
  if(document.hidden)automaticSave();
});
window.addEventListener("blur",()=>{
  if(active)rpc("release").catch(()=>{});
});
setInterval(automaticSave,60000);

async function launch(){
  const dialog=document.createElement("dialog");
  dialog.style.cssText="max-width:420px;width:calc(100% - 64px);"+
    "border:1px solid #879bb3;border-radius:16px;padding:24px;"+
    "font:16px system-ui";
  dialog.innerHTML=`
    <h2>CG50 Pro Max</h2>
    <p id="ipad-status">Loading saved calculator…</p>
    <div id="ipad-import" hidden>
      <p>首次使用，请选择固件和进度；已有数据会自动恢复。</p>
      <p>Firmware <input id="ipad-flash" type="file" accept=".bin"></p>
      <p>Saved progress <input id="ipad-state" type="file" accept=".bin"></p>
      <button id="ipad-start">Import and start</button>
    </div>`;
  document.body.append(dialog);
  dialog.addEventListener("cancel",e=>e.preventDefault());
  dialog.addEventListener("keydown",e=>e.stopPropagation());
  dialog.addEventListener("keyup",e=>e.stopPropagation());
  dialog.showModal();
  try{

    /* CG50 AUTOMATIC DEFAULTS */
    let [flash,state]=await Promise.all([read("flash"),read("state")]);
    if(!flash && !state){
      notify("首次准备，请稍候… / Preparing first launch…");
      async function download(name){
        const controller=new AbortController();
        const timer=setTimeout(()=>controller.abort(),120000);
        try{
          const response=await networkFetch("./defaults/"+name,{
            signal:controller.signal
          });
          if(!response.ok)throw Error("Download failed: "+name);
          return await response.arrayBuffer();
        }finally{clearTimeout(timer);}
      }
      [flash,state]=await Promise.all([
        download("flash_full.bin"),download("cg50_state.bin")
      ]);
      if(flash.byteLength!==33554432 || !state.byteLength)
        throw Error("Initial data is incomplete");
      await write({flash,state});
    }
    if(!flash || !state)
      throw Error("Local data incomplete; existing progress preserved.");

    if(flash&&state){
      await boot(flash,state);dialog.close();
    }else{
      document.getElementById("ipad-import").hidden=false;
      notify("First-time setup");
    }
  }catch(e){
    notify("启动失败 / Startup failed: "+e.message);
        const retry=document.createElement("button");
        retry.textContent="重试 / Retry";
        retry.onclick=()=>location.reload();
        dialog.append(retry);
    document.getElementById("ipad-import").hidden=false;
  }
  document.getElementById("ipad-start").onclick=async()=>{
    const button=document.getElementById("ipad-start");
    button.disabled=true;
    try{
      const f=document.getElementById("ipad-flash").files[0];
      const s=document.getElementById("ipad-state").files[0];
      if(!f||!s)throw Error("Choose both files");
      if(f.size!==33554432)throw Error("Firmware must be 32 MiB");
      const flash=await f.arrayBuffer(),state=await s.arrayBuffer();
      await boot(flash,state);
      await write({flash,state});
      dialog.close();
      navigator.storage?.persist?.().catch(()=>{});
    }catch(e){notify(e.message);}
    finally{button.disabled=false;}
  };

  // Standalone backup control, separate from native Mac menu actions.
  const backup=document.createElement("button");
  backup.textContent="Export backup / 导出备份";
  backup.style.cssText="display:block;margin:16px auto;padding:8px 12px";
  backup.onclick=async()=>{
    try{
      if(active&&!fault)await snapshot();
      const state=await read("state");
      if(!state)throw Error("No saved progress");
      const url=URL.createObjectURL(new Blob([state]));
      const a=document.createElement("a");
      a.href=url;a.download="cg50-ipad-state.bin";a.click();
      setTimeout(()=>URL.revokeObjectURL(url),60000);
    }catch(e){alert(e.message);}
  };
  document.body.append(backup);
  if("serviceWorker" in navigator){
    try{await navigator.serviceWorker.register("./sw.js");}
    catch(e){console.warn("Offline setup failed",e);}
  }
}
document.addEventListener("DOMContentLoaded",launch,{once:true});
})();

const CACHE="cg50-release-v1.1.0-792bdc0b85359296";
const RELEASE={"app": "CG50 Pro Max", "version": "1.1.0", "releaseId": "v1.1.0-20261013-161753", "graphicsAcceleration": true, "notesZh": ["支持设备上的触屏轻震反馈，并保留按键高亮。", "画图忙时自动加速，空闲时降低占用。", "新增版本号与更新说明弹窗。", "左上角显示联网同步、更新或离线状态。", "重载配置文件后显示成功或失败，成功时显示版本号。", "新用户采用未初始化的初始存档；已有进度保留。"], "notesEn": ["Touch vibration on supported devices, with visual key feedback.", "Automatic acceleration while busy and reduced work while idle.", "Version information and release notes.", "Online, update and offline status in the header.", "Reload result feedback with the installed version.", "An uninitialized starting state for new users. Existing progress is retained."]};
const FILES=["./", "./build-info.json", "./calculator-front.png", "./cg50-display.js", "./cg50-features.js", "./cg50-update.js", "./cg50.wasm", "./defaults/cg50_state.bin", "./defaults/flash_full.bin", "./icon-180.png", "./icon-192.png", "./icon-512.png", "./index.html", "./ipad-adapter.js", "./manifest.webmanifest", "./wasm_exec.js", "./worker.js"];

self.addEventListener("install",event=>{
  event.waitUntil((async()=>{
    try{
      const cache=await caches.open(CACHE);
      await cache.addAll(FILES);
      if(!self.registration.active)await self.skipWaiting();
    }catch(error){
      await caches.delete(CACHE);throw error;
    }
  })());
});
self.addEventListener("message",event=>{
  if(event.data==="ACTIVATE_UPDATE"){
    event.waitUntil(self.skipWaiting());
  }else if(event.data==="GET_RELEASE"&&event.ports[0]){
    event.ports[0].postMessage(RELEASE);
    event.ports[0].close();
  }else if(event.data==="check-offline"&&event.ports[0]){
    event.waitUntil((async()=>{
      const cache=await caches.open(CACHE);
      const results=await Promise.all(FILES.map(file=>cache.match(file)));
      event.ports[0].postMessage(results.every(Boolean)
        ?"offline-ready":"offline-incomplete");
      event.ports[0].close();
    })());
  }
});
self.addEventListener("activate",event=>{
  event.waitUntil((async()=>{
    await self.clients.claim();
    for(const key of await caches.keys()){
      if(key!==CACHE&&(key.startsWith("cg50-release-")||
          key.startsWith("cg50-auto-update-"))){
        await caches.delete(key);
      }
    }
  })());
});
self.addEventListener("fetch",event=>{
  const url=new URL(event.request.url);
  if(event.request.method!=="GET"||url.origin!==self.location.origin)return;
  // 握手必须访问服务器，不能用离线缓存假装在线。
  if(url.pathname.endsWith("/version.json")){
    event.respondWith(fetch(new Request(event.request,{cache:"no-store"})));
    return;
  }
  url.search="";url.hash="";
  event.respondWith((async()=>{
    const cache=await caches.open(CACHE);
    return await cache.match(url.href)||fetch(event.request);
  })());
});

